    <!-- ======================= ALUMNI INQUIRY FORM ======================= -->

    <section class="alumni-form-section py-5">
        <div class="container">

            <h2 class="alumni-form-title text-center">Alumni Inquiry Form</h2>
            <p class="alumni-form-sub text-center">
                We'd love to hear from you! Whether you want to reconnect, volunteer, or share your journey.
                Fill out the form below and join the growing Redwood alumni network.
            </p>

            <div class="alumni-form-box mx-auto">

                <form>

                    <div class="row">
                        <div class="col-md-6 mb-3">
                            <label class="form-label">First Name</label>
                            <input type="text" class="form-control form-input">
                        </div>

                        <div class="col-md-6 mb-3">
                            <label class="form-label">Last Name</label>
                            <input type="text" class="form-control form-input">
                        </div>

                        <div class="col-md-6 mb-3">
                            <label class="form-label">Year</label>
                            <select class="form-select form-input">
                                <option>2024</option>
                                <option>2023</option>
                                <option>2022</option>
                            </select>
                        </div>

                        <div class="col-md-6 mb-3">
                            <label class="form-label">Team</label>
                            <select class="form-select form-input">
                                <option>Varsity</option>
                                <option>JV</option>
                            </select>
                        </div>

                        <div class="col-12 mb-3">
                            <label class="form-label">Email</label>
                            <input type="email" class="form-control form-input">
                        </div>

                        <div class="col-12 mb-3">
                            <label class="form-label">Your Involvement Interest</label>

                            <div class="d-flex gap-4 mt-2 involvement-options">
                                <label><input type="checkbox"> Mentorship</label>
                                <label><input type="checkbox"> Volunteering</label>
                                <label><input type="checkbox"> Sponsorship</label>
                            </div>
                        </div>

                        <div class="col-12 mb-3">
                            <label class="form-label">Leave a Comment</label>
                            <textarea class="form-control form-input" rows="5"></textarea>
                        </div>

                    </div>

                    <div class="text-end mt-4">
                        <button class="send-btn">Send Inquiry</button>
                    </div>

                </form>

            </div>

        </div>
        <div class="modal fade" id="imageModal" tabindex="-1">
            <div class="modal-dialog modal-fullscreen">
                <div class="modal-content" style="background:black;">
                    <span class="close-modal-btn" data-bs-dismiss="modal">&times;</span>
                    <img id="modalImage" class="modal-full-image">
                </div>
            </div>
        </div>
    </section>




